WITH with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM sessions), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT id, customer_id, browser, started_at, country, session_id, CASE WHEN browser RLIKE '^(Edge|Safari)$' THEN 'PRIORITY' ELSE 'CORE' END AS browser_zone FROM islands ORDER BY id DESC NULLS FIRST, country LIMIT 20;
